        eprintln!("  dog example.net MX @1.1.1.1 -T           ...using TCP rather than UDP");
        eprintln!("  dog -q example.net -t MX -n 1.1.1.1 -T   As above, but using explicit arguments\n");
        eprintln!("Query options:");
        eprintln!("  <arguments>              Human-readable host names, nameservers, types, or classes");
        eprintln!("  -q, --query=HOST         Host name or domain name to query");
        eprintln!("  -t, --type=TYPE          Type of the DNS record being queried (A, MX, NS...)");
        eprintln!("  -n, --nameserver=ADDR    Address of the nameserver to send packets to");
        eprintln!("  --class=CLASS            Network class of the DNS record being queried (IN, CH, HS)\n");
        eprintln!("Sending options:");
        eprintln!("  --edns=SETTING           Whether to OPT in to EDNS (disable, hide, show)");
        eprintln!("  --txid=NUMBER            Set the transaction ID to a specific value");
        eprintln!("  -Z=TWEAKS                Set uncommon protocol-level tweaks\n");
        eprintln!("Protocol options:");
        eprintln!("  -U, --udp                Use the DNS protocol over UDP");
        eprintln!("  -T, --tcp                Use the DNS protocol over TCP");
        eprintln!("  -S, --tls                Use the DNS-over-TLS protocol");
        eprintln!("  -H, --https              Use the DNS-over-HTTPS protocol\n");
        eprintln!("Output options:");
        eprintln!("  -1, --short              Short mode: display nothing but the first result");
        eprintln!("  -J, --json               Display the output as JSON");
        eprintln!("  --color, --colour=WHEN   When to colourise the output (always, automatic, never)");
        eprintln!("  --seconds                Do not format durations, display them as seconds");
        eprintln!("  --time                   Print how long the response took to arrive\n");
        eprintln!("Meta options:");
        eprintln!("  -?, --help               Print list of command-line options");
        eprintln!("  -v, --version            Print version information");
        std::process::exit(3);
    }

    let start = Instant::now();

    // Perform DNS queries
    match perform_dns_queries(&domains, &types, &nameservers, &args).await {
        Ok(results) => {
            if args.json {
                println!("{}", serde_json::to_string(&results).unwrap());
            } else {
                for result in results {
                    for answer in &result["answers"] {
                        let name = answer["name"].as_str().unwrap_or("");
                        let ttl = answer["ttl"].as_u64().unwrap_or(0);
                        let type_ = answer["type"].as_str().unwrap_or("");
