                            format_ttl(ttl)
                        };

                        let data_str = format_data(data, type_);
                        println!("{} {} {}   {}", type_, name, ttl_str, data_str);
                    }
                }
            }

            if args.time {
                let elapsed = start.elapsed().as_millis();
                println!("Ran in {}ms", elapsed);
            }

            std::process::exit(0);
        }
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
