fn is_record_type(s: &str) -> bool {
    matches!(s.to_uppercase().as_str(),
        "A" | "AAAA" | "CAA" | "CNAME" | "HINFO" | "LOC" | "MX" | "NAPTR" |
        "NS" | "OPT" | "PTR" | "SOA" | "SRV" | "SSHFP" | "TLSA" | "TXT" |
        "IXFR" | "ANY" | "AFSDB"
    )
}

fn format_ttl(seconds: u64) -> String {
    let mut remaining = seconds;
    let mut parts = Vec::new();

    let hours = remaining / 3600;
    remaining %= 3600;

    let minutes = remaining / 60;
    let secs = remaining % 60;

    if hours > 0 {
        let days = hours / 24;
        let hrs = hours % 24;
        if days > 0 {
            parts.push(format!("{}d", days));
        }
        if hrs > 0 {
            parts.push(format!("{}h", hrs));
        }
    }
    if minutes > 0 {
        parts.push(format!("{}m", minutes));
    }
    if secs > 0 {
        parts.push(format!("{}s", secs));
    }

    if parts.is_empty() {
        "0s".to_string()
    } else {
        parts.join("")
    }
}

fn format_data(data: &serde_json::Value, type_: &str) -> String {
    match type_ {
        "A" | "AAAA" => {
            data.get("address")
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .to_string()
        }
        "MX" => {
            let priority = data.get("priority").and_then(|v| v.as_u64()).unwrap_or(0);
            let exchange = data.get("exchange").and_then(|v| v.as_str()).unwrap_or("");
            if priority == 0 {
                format!("\"{}\"", exchange)
            } else {
                format!("{} {}", priority, exchange)
            }
        }
        "NS" | "CNAME" | "PTR" => {
            data.get("nameserver")
                .or_else(|| data.get("cname"))
                .or_else(|| data.get("target"))
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .to_string()
        }
        "TXT" => {
            data.get("data")
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .to_string()
        }
        _ => format!("{}", data),
    }
}

async fn perform_dns_queries(
    domains: &[String],
    types: &[String],
    nameservers: &[String],
    args: &Args,
) -> anyhow::Result<Vec<serde_json::Value>> {
    let mut results = Vec::new();

    for domain in domains {
        for type_str in types {
            let result = perform_single_query(domain, type_str, nameservers, args).await?;
            results.push(result);
        }
    }

    Ok(results)
}

async fn perform_single_query(
    domain: &str,
    type_str: &str,
    nameservers: &[String],
    args: &Args,
) -> anyhow::Result<serde_json::Value> {
    // Create a resolver
    let mut resolver_config = ResolverConfig::new();

    if !nameservers.is_empty() {
        for ns in nameservers {
            if let Ok(addr) = ns.parse::<SocketAddr>() {
                resolver_config.add_name_server(NameServerConfig {
                    socket_addr: addr,
                    protocol: trust_dns_resolver::config::trust_dns_proto::xfer::ProtocolMode::Udp,
                    trust_negative_responses: false,
                    tls_dns_name: None,
                });
            } else if let Ok(ip) = ns.parse::<IpAddr>() {
                let addr = SocketAddr::new(ip, 53);
                resolver_config.add_name_server(NameServerConfig {
                    socket_addr: addr,
                    protocol: trust_dns_resolver::config::trust_dns_proto::xfer::ProtocolMode::Udp,
                    trust_negative_responses: false,
                    tls_dns_name: None,
                });
            } else {
                return Err(anyhow::anyhow!("Invalid nameserver: {}", ns));
            }
        }
    } else {
        resolver_config = ResolverConfig::from_system_conf()?;
    }

    let resolver = TokioAsyncResolver::tokio(resolver_config, Default::default());

    let name = Name::from_utf8(domain)?;
    let record_type = parse_record_type(type_str)?;

    let response = resolver.lookup(name.clone(), record_type).await?;

    // Format the response
    let mut answers = Vec::new();
    for record in response.record_iter() {
        let answer = format_answer(record)?;
        answers.push(answer);
    }

    let query_obj = json!({
        "name": domain,
        "class": "IN",
        "type": type_str
    });

    Ok(json!({
        "queries": [query_obj],
        "answers": answers,
        "authorities": [],
        "additionals": []
    }))
}

fn parse_record_type(type_str: &str) -> anyhow::Result<trust_dns_proto::rr::RecordType> {
    match type_str.to_uppercase().as_str() {
        "A" => Ok(trust_dns_proto::rr::RecordType::A),
        "AAAA" => Ok(trust_dns_proto::rr::RecordType::AAAA),
        "MX" => Ok(trust_dns_proto::rr::RecordType::MX),
        "NS" => Ok(trust_dns_proto::rr::RecordType::NS),
        "CNAME" => Ok(trust_dns_proto::rr::RecordType::CNAME),
        "TXT" => Ok(trust_dns_proto::rr::RecordType::TXT),
        "PTR" => Ok(trust_dns_proto::rr::RecordType::PTR),
        "SOA" => Ok(trust_dns_proto::rr::RecordType::SOA),
        "SRV" => Ok(trust_dns_proto::rr::RecordType::SRV),
        "CAA" => Ok(trust_dns_proto::rr::RecordType::CAA),
        "TLSA" => Ok(trust_dns_proto::rr::RecordType::TLSA),
        _ => Err(anyhow::anyhow!("Unknown record type: {}", type_str)),
    }
}

fn format_answer(record: &trust_dns_proto::rr::Record) -> anyhow::Result<serde_json::Value> {
    let name = format!("{}", record.name());
    let ttl = record.ttl();
    let type_str = format!("{}", record.record_type());

    let data = match record.record_type() {
        trust_dns_proto::rr::RecordType::A => {
            if let Some(a_record) = record.data().and_then(|d| d.as_a()) {
                json!({ "address": a_record.to_string() })
            } else {
                json!({})
            }
        }
        trust_dns_proto::rr::RecordType::AAAA => {
            if let Some(aaaa_record) = record.data().and_then(|d| d.as_aaaa()) {
                json!({ "address": aaaa_record.to_string() })
            } else {
                json!({})
            }
        }
        trust_dns_proto::rr::RecordType::MX => {
            if let Some(mx_record) = record.data().and_then(|d| d.as_mx()) {
                json!({
                    "priority": mx_record.preference(),
                    "exchange": mx_record.exchange().to_utf8()
                })
            } else {
                json!({})
            }
        }
        trust_dns_proto::rr::RecordType::NS => {
            if let Some(ns_record) = record.data().and_then(|d| d.as_ns()) {
                json!({ "nameserver": ns_record.to_utf8() })
            } else {
                json!({})
            }
        }
        trust_dns_proto::rr::RecordType::CNAME => {
            if let Some(cname_record) = record.data().and_then(|d| d.as_cname()) {
                json!({ "cname": cname_record.to_utf8() })
            } else {
                json!({})
            }
        }
        trust_dns_proto::rr::RecordType::TXT => {
            if let Some(txt_record) = record.data().and_then(|d| d.as_txt()) {
                let data_str = txt_record.iter()
                    .flat_map(|d| d.iter())
                    .map(|&b| b as char)
                    .collect::<String>();
                json!({ "data": data_str })
            } else {
                json!({})
            }
        }
        trust_dns_proto::rr::RecordType::PTR => {
            if let Some(ptr_record) = record.data().and_then(|d| d.as_ptr()) {
                json!({ "target": ptr_record.to_utf8() })
            } else {
                json!({})
            }
        }
        trust_dns_proto::rr::RecordType::SOA => {
            if let Some(soa_record) = record.data().and_then(|d| d.as_soa()) {
                json!({
                    "mname": soa_record.mname().to_utf8(),
                    "rname": soa_record.rname().to_utf8(),
                    "serial": soa_record.serial(),
                    "refresh": soa_record.refresh(),
                    "retry": soa_record.retry(),
                    "expire": soa_record.expire(),
                    "minimum": soa_record.minimum()
                })
            } else {
                json!({})
            }
        }
        _ => json!({}),
    };

    Ok(json!({
        "name": name,
        "class": "IN",
        "ttl": ttl,
        "type": type_str,
        "data": data
    }))
}
