fn dns_lookup(domain: &str, record_type: &str, _nameservers: &[String]) -> Result<Vec<DnsRecord>, String> {
    // Use system DNS resolution via getaddrinfo
    // This is a simplified implementation that uses system DNS

    let domain_with_dot = if domain.ends_with('.') {
        domain.to_string()
    } else {
        format!("{}.", domain)
    };

    match record_type {
        "A" => {
            // Use system DNS to get A records
            match (domain, 0).to_socket_addrs() {
                Ok(addrs) => {
                    let mut records = Vec::new();
                    for addr in addrs {
                        if let std::net::SocketAddr::V4(v4) = addr {
                            records.push(DnsRecord {
                                name: domain_with_dot.clone(),
                                ttl: 300, // Default TTL
                                data: v4.ip().to_string(),
                            });
                        }
                    }

                    // Remove duplicates
                    records.sort_by(|a, b| a.data.cmp(&b.data));
                    records.dedup_by(|a, b| a.data == b.data);

                    if records.is_empty() {
                        Err("No A records found".to_string())
                    } else {
                        Ok(records)
                    }
                }
                Err(e) => Err(format!("[network]: {}", e)),
            }
        }
        "AAAA" => {
            match (domain, 0).to_socket_addrs() {
                Ok(addrs) => {
                    let mut records = Vec::new();
                    for addr in addrs {
                        if let std::net::SocketAddr::V6(v6) = addr {
                            records.push(DnsRecord {
                                name: domain_with_dot.clone(),
                                ttl: 300,
                                data: v6.ip().to_string(),
                            });
                        }
                    }
                    if records.is_empty() {
                        Err("No AAAA records found".to_string())
                    } else {
                        Ok(records)
                    }
                }
                Err(e) => Err(format!("[network]: {}", e)),
            }
        }
        _ => {
            // For other record types, we'd need proper DNS protocol implementation
            // For now, just return error
            Err(format!("Record type {} not yet implemented", record_type))
        }
    }
}

fn format_json(records: &[DnsRecord], domain: &str, record_type: &str) -> String {
    let mut answers = Vec::new();
    for record in records {
        answers.push(format!(
            r#"{{"name":"{}","class":"IN","ttl":{},"type":"{}","data":{{"address":"{}"}}}}"#,
            record.name, record.ttl, record_type, record.data
        ));
    }

    let answers_str = answers.join(",");
    format!(
        r#"{{"responses":[{{"queries":[{{"name":"{}.","class":"IN","type":"{}"}}],"answers":[{}],"authorities":[],"additionals":[]}}]}}"#,
        domain, record_type, answers_str
    )
}
