            if pos + 1 + len > response.len() {
                return Err("Invalid label".to_string());
            }
            let label = String::from_utf8_lossy(&response[pos + 1..pos + 1 + len]).to_string();
            labels.push(label);
            pos += 1 + len;
        }
    }

    Ok((labels, pos))
}

fn format_domain_name(labels: &[String]) -> String {
    if labels.is_empty() {
        ".".to_string()
    } else {
        format!("{}.", labels.join("."))
    }
}

fn parse_rdata(rdata: &[u8], record_type: u16, response: &[u8]) -> Result<String, String> {
    match record_type {
        1 => {
            // A record - 4 bytes IPv4 address
            if rdata.len() != 4 {
                return Err("Invalid A record".to_string());
            }
            Ok(format!("{}.{}.{}.{}", rdata[0], rdata[1], rdata[2], rdata[3]))
        }
        2 => {
            // NS record - domain name
            let (labels, _) = parse_domain_name(response, {
