            if rdata.len() < 2 {
                return Err("Invalid MX record".to_string());
            }
            let preference = u16::from_be_bytes([rdata[0], rdata[1]]);
            let (labels, _) = parse_domain_name(response, {
                let ptr = rdata.as_ptr() as usize;
                let resp_ptr = response.as_ptr() as usize;
                if ptr + 2 >= resp_ptr && ptr + 2 < resp_ptr + response.len() {
                    ptr + 2 - resp_ptr
                } else {
