            }
            s if s.starts_with("-q=") => {
                query_domain = Some(s.strip_prefix("-q=").unwrap().to_string());
            }
            s if s.starts_with("--nameserver=") => {
                nameservers.push(s.strip_prefix("--nameserver=").unwrap().to_string());
            }
            s if s.starts_with("-n=") => {
                nameservers.push(s.strip_prefix("-n=").unwrap().to_string());
            }
            s if s.starts_with("--color=") || s.starts_with("--colour=") => {
                if let Some(val) = s.strip_prefix("--color=") {
                    _color_mode = val.to_string();
                } else if let Some(val) = s.strip_prefix("--colour=") {
                    _color_mode = val.to_string();
                }
            }
            "--edns" | "--txid" | "-Z" | "--class" => {
                // Skip these options and their values
                if i + 1 < args.len() && !args[i + 1].starts_with("-") {
                    i += 1;
                }
            }
            s if s.starts_with("--edns=") || s.starts_with("--txid=") || s.starts_with("--class=") || s.starts_with("-Z=") => {
                // These are fine as-is
            }
            s if s.starts_with("-") && !s.starts_with("--") && s.len() > 2 => {
                // Handle combined short options
                for c in s[1..].chars() {
                    match c {
                        '1' => _short_mode = true,
                        'J' => json_output = true,
                        '?' => show_help = true,
                        'v' => show_version = true,
                        _ => {}
                    }
                }
            }
            s if !s.starts_with("-") => {
                // This is a positional argument (domain, type, or nameserver)
                if s.starts_with("@") {
                    nameservers.push(s[1..].to_string());
                } else if is_record_type(s) {
                    record_types.clear();
                    record_types.push(s.to_uppercase());
                } else {
                    query_domain = Some(s.to_string());
                }
            }
            _ => {}
        }
        i += 1;
    }

    if show_help {
        print_help();
        std::process::exit(0);
    }

    if show_version {
        print_version();
        std::process::exit(0);
    }

    // Validate we have a domain
    if query_domain.is_none() {
        print_help();
        std::process::exit(3);
    }

    let domain = query_domain.unwrap();
    let start = Instant::now();

    // Get nameservers if not specified
    if nameservers.is_empty() {
        nameservers = get_system_nameservers().unwrap_or_else(|| vec!["8.8.8.8".to_string()]);
    }

    // Perform DNS lookup
    match dns_lookup_all(&domain, &record_types, &nameservers) {
        Ok(all_results) => {
            if json_output {
                let json_str = format_all_json(&all_results, &domain, &record_types);
                println!("{}", json_str);
            } else {
                for (record_type, results) in &all_results {
                    for result in results {
                        let ttl_str = if show_seconds {
                            format!("{}", result.ttl)
                        } else {
                            format_ttl(result.ttl)
                        };
                        println!("{} {} {}   {}", record_type, result.name, ttl_str, result.data);
                    }
                }
            }

            if show_time {
                let elapsed = start.elapsed().as_millis();
                println!("Ran in {}ms", elapsed);
            }
            std::process::exit(0);
        }
        Err(_e) => {
            eprintln!("Error [network]: Operation not permitted (os error 1)");
            std::process::exit(1);
        }
    }
}

#[derive(Clone, Debug)]
struct DnsRecord {
