fn get_system_nameservers() -> Option<Vec<String>> {
    // Try to read /etc/resolv.conf
    if let Ok(content) = std::fs::read_to_string("/etc/resolv.conf") {
        let mut servers = Vec::new();
        for line in content.lines() {
            if line.starts_with("nameserver") {
                if let Some(ip) = line.split_whitespace().nth(1) {
                    servers.push(ip.to_string());
                }
            }
        }
        if !servers.is_empty() {
            return Some(servers);
        }
    }
    None
}

fn dns_lookup_all(domain: &str, record_types: &[String], nameservers: &[String]) -> Result<Vec<(String, Vec<DnsRecord>)>, String> {
    let mut all_results = Vec::new();

    for record_type in record_types {
        match dns_lookup(domain, record_type, nameservers) {
            Ok(records) => {
                all_results.push((record_type.clone(), records));
            }
            Err(e) => {
                return Err(e);
            }
        }
    }

    Ok(all_results)
}

fn dns_lookup(domain: &str, record_type: &str, nameservers: &[String]) -> Result<Vec<DnsRecord>, String> {
    let record_type_code = match record_type {
        "A" => 1,
        "NS" => 2,
        "CNAME" => 5,
        "SOA" => 6,
        "MX" => 15,
        "TXT" => 16,
        "AAAA" => 28,
        "LOC" => 29,
        "SRV" => 33,
        "NAPTR" => 35,
        "CAA" => 257,
        "TLSA" => 52,
        "SSHFP" => 44,
        "HINFO" => 13,
        "PTR" => 12,
        _ => return Err("Unknown record type".to_string()),
    };

    // Get a nameserver to query
    let nameserver = if !nameservers.is_empty() {
        nameservers[0].clone()
    } else {
        return Err("No nameserver available".to_string());
    };

    // Build DNS query
    let query = build_dns_query(domain, record_type_code)?;

    // Send query and get response
    let response = send_dns_query(&query, &nameserver)?;

    // Parse response
    parse_dns_response(&response, domain, record_type)
}

fn build_dns_query(domain: &str, record_type: u16) -> Result<Vec<u8>, String> {
    let mut query = Vec::new();

    // Transaction ID (2 bytes) - using 0x1234
    query.push(0x12);
    query.push(0x34);

    // Flags (2 bytes) - standard query
    query.push(0x01);
    query.push(0x00);

    // Questions (2 bytes)
    query.push(0x00);
    query.push(0x01);

    // Answer RRs (2 bytes)
    query.push(0x00);
    query.push(0x00);

    // Authority RRs (2 bytes)
    query.push(0x00);
    query.push(0x00);

    // Additional RRs (2 bytes)
    query.push(0x00);
    query.push(0x00);

    // Question section
    // Domain name (labels)
    for label in domain.split('.') {
        if !label.is_empty() {
            query.push(label.len() as u8);
            query.extend_from_slice(label.as_bytes());
        }
    }
    query.push(0x00); // End of domain name

    // Type (2 bytes)
    query.push((record_type >> 8) as u8);
    query.push((record_type & 0xFF) as u8);

    // Class (2 bytes) - IN
    query.push(0x00);
    query.push(0x01);

    Ok(query)
}

fn send_dns_query(query: &[u8], nameserver: &str) -> Result<Vec<u8>, String> {
    let addr_port = if nameserver.contains(':') {
        nameserver.to_string()
    } else {
        format!("{}:53", nameserver)
    };

    let socket_addr: SocketAddr = addr_port.parse()
        .map_err(|_| "Invalid nameserver address".to_string())?;

    let socket = UdpSocket::bind("0.0.0.0:0")
        .map_err(|e| format!("Failed to bind socket: {}", e))?;

    socket.send_to(query, socket_addr)
        .map_err(|e| format!("Failed to send query: {}", e))?;

    let mut response = vec![0; 4096];
    let (n, _) = socket.recv_from(&mut response)
        .map_err(|e| format!("Failed to receive response: {}", e))?;

    response.truncate(n);
    Ok(response)
}

fn parse_dns_response(response: &[u8], _domain: &str, record_type: &str) -> Result<Vec<DnsRecord>, String> {
    if response.len() < 12 {
        return Err("Response too short".to_string());
    }

    // Skip header (12 bytes)
    let mut pos = 12;

    // Skip questions
    let num_questions = u16::from_be_bytes([response[4], response[5]]) as usize;
    for _ in 0..num_questions {
        // Skip domain name
        while pos < response.len() && response[pos] != 0 {
            if response[pos] & 0xC0 == 0xC0 {
                // Compression pointer
                pos += 2;
                break;
            } else {
                let len = response[pos] as usize;
                pos += len + 1;
            }
        }
        if pos < response.len() {
            pos += 1; // Skip null terminator
        }
        pos += 4; // Skip type and class
    }

    // Parse answer section
    let num_answers = u16::from_be_bytes([response[6], response[7]]) as usize;
    let mut records = Vec::new();

    for _ in 0..num_answers {
        if pos >= response.len() {
            break;
        }

        // Parse name (may use compression)
        let (name, new_pos) = parse_domain_name(response, pos)?;
        pos = new_pos;

        if pos + 10 > response.len() {
            break;
        }

        let ans_type = u16::from_be_bytes([response[pos], response[pos + 1]]);
        let _ans_class = u16::from_be_bytes([response[pos + 2], response[pos + 3]]);
        let ttl = u32::from_be_bytes([response[pos + 4], response[pos + 5], response[pos + 6], response[pos + 7]]);
        let rdlen = u16::from_be_bytes([response[pos + 8], response[pos + 9]]) as usize;
        pos += 10;

        if pos + rdlen > response.len() {
            break;
        }

        // Check if this record matches the type we're looking for
        let type_code = match record_type {
            "A" => 1,
            "NS" => 2,
            "CNAME" => 5,
            "SOA" => 6,
            "MX" => 15,
            "TXT" => 16,
            "AAAA" => 28,
            "LOC" => 29,
            "SRV" => 33,
            "NAPTR" => 35,
            "CAA" => 257,
            "TLSA" => 52,
            "SSHFP" => 44,
            "HINFO" => 13,
            "PTR" => 12,
            _ => 0,
        };

        if ans_type == type_code {
            let rdata = &response[pos..pos + rdlen];
            let record_data = parse_rdata(rdata, ans_type, response)?;

            records.push(DnsRecord {
                name: format_domain_name(&name),
                ttl,
                data: record_data,
            });
        }

        pos += rdlen;
    }

    Ok(records)
}

fn parse_domain_name(response: &[u8], mut pos: usize) -> Result<(Vec<String>, usize), String> {
    let mut labels = Vec::new();
    let mut visited = std::collections::HashSet::new();

    loop {
        if pos >= response.len() {
            return Err("Invalid domain name".to_string());
        }

        if visited.contains(&pos) {
            return Err("Infinite loop in domain name".to_string());
        }
        visited.insert(pos);

        let len = response[pos] as usize;

        if len == 0 {
            // End of name
            pos += 1;
            break;
        } else if len & 0xC0 == 0xC0 {
            // Compression pointer
            if pos + 1 >= response.len() {
                return Err("Invalid compression pointer".to_string());
            }
            let ptr = (((len & 0x3F) as usize) << 8) | (response[pos + 1] as usize);
            pos += 2;

            // Recursively parse the compressed part
            let (compressed_labels, _) = parse_domain_name(response, ptr)?;
            labels.extend(compressed_labels);
            break;
        } else {
            // Label
            if pos + 1 + len > response.len() {
                return Err("Invalid label".to_string());
            }
            let label = String::from_utf8_lossy(&response[pos + 1..pos + 1 + len]).to_string();
            labels.push(label);
            pos += 1 + len;
        }
    }

    Ok((labels, pos))
}

fn format_domain_name(labels: &[String]) -> String {
    if labels.is_empty() {
        ".".to_string()
    } else {
        format!("{}.", labels.join("."))
    }
}

fn parse_rdata(rdata: &[u8], record_type: u16, response: &[u8]) -> Result<String, String> {
    match record_type {
        1 => {
            // A record - 4 bytes IPv4 address
            if rdata.len() != 4 {
                return Err("Invalid A record".to_string());
            }
            Ok(format!("{}.{}.{}.{}", rdata[0], rdata[1], rdata[2], rdata[3]))
        }
        2 => {
            // NS record - domain name
            let (labels, _) = parse_domain_name(response, {
                // Find the position in response
                let ptr = rdata.as_ptr() as usize;
                let resp_ptr = response.as_ptr() as usize;
                if ptr >= resp_ptr && ptr < resp_ptr + response.len() {
                    ptr - resp_ptr
                } else {
                    0
                }
            })?;
            let domain = format_domain_name(&labels);
            // Remove quotes if they exist
            if domain == "." {
                Ok("\"\"".to_string())
            } else {
                Ok(format!("\"{}\"", domain))
            }
        }
        5 => {
            // CNAME record - domain name
            let (labels, _) = parse_domain_name(response, {
                let ptr = rdata.as_ptr() as usize;
                let resp_ptr = response.as_ptr() as usize;
                if ptr >= resp_ptr && ptr < resp_ptr + response.len() {
                    ptr - resp_ptr
                } else {
                    0
                }
            })?;
            Ok(format_domain_name(&labels))
        }
        6 => {
            // SOA record
            Ok("SOA".to_string())
        }
        15 => {
            // MX record - preference (2 bytes) + exchange (domain name)
            if rdata.len() < 2 {
                return Err("Invalid MX record".to_string());
            }
            let preference = u16::from_be_bytes([rdata[0], rdata[1]]);
            let (labels, _) = parse_domain_name(response, {
                let ptr = rdata.as_ptr() as usize;
                let resp_ptr = response.as_ptr() as usize;
                if ptr + 2 >= resp_ptr && ptr + 2 < resp_ptr + response.len() {
                    ptr + 2 - resp_ptr
                } else {
                    0
                }
            })?;
            let domain = format_domain_name(&labels);
            let domain_str = if domain == "." {
                "\"\"".to_string()
            } else {
                format!("\"{}\"", domain)
            };
            Ok(format!("{} {}", preference, domain_str))
        }
        16 => {
            // TXT record - strings
            let mut text = String::new();
            let mut pos = 0;
            while pos < rdata.len() {
                let len = rdata[pos] as usize;
                pos += 1;
                if pos + len > rdata.len() {
                    break;
                }
                text.push_str(&String::from_utf8_lossy(&rdata[pos..pos + len]));
                pos += len;
            }
            Ok(format!("\"{}\"", text))
        }
        28 => {
            // AAAA record - 16 bytes IPv6 address
            if rdata.len() != 16 {
                return Err("Invalid AAAA record".to_string());
            }
            let addr = std::net::Ipv6Addr::new(
                u16::from_be_bytes([rdata[0], rdata[1]]),
                u16::from_be_bytes([rdata[2], rdata[3]]),
                u16::from_be_bytes([rdata[4], rdata[5]]),
                u16::from_be_bytes([rdata[6], rdata[7]]),
                u16::from_be_bytes([rdata[8], rdata[9]]),
                u16::from_be_bytes([rdata[10], rdata[11]]),
                u16::from_be_bytes([rdata[12], rdata[13]]),
                u16::from_be_bytes([rdata[14], rdata[15]]),
            );
            Ok(addr.to_string())
        }
        12 => {
            // PTR record - domain name
            let (labels, _) = parse_domain_name(response, {
                let ptr = rdata.as_ptr() as usize;
                let resp_ptr = response.as_ptr() as usize;
                if ptr >= resp_ptr && ptr < resp_ptr + response.len() {
                    ptr - resp_ptr
                } else {
                    0
                }
            })?;
            Ok(format_domain_name(&labels))
        }
        _ => Ok(format!("{:?}", rdata))
    }
}

fn format_json(records: &[(String, Vec<DnsRecord>)], domain: &str, _record_types: &[String]) -> String {
    let mut all_answers = Vec::new();

    for (type_name, recs) in records {
        for record in recs {
            all_answers.push(format!(
                r#"{{"name":"{}","class":"IN","ttl":{},"type":"{}","data":{{"address":"{}"}}}}"#,
                record.name, record.ttl, type_name, record.data
            ));
        }
    }

    let answers_str = all_answers.join(",");
    format!(
        r#"{{"responses":[{{"queries":[{{"name":"{}.","class":"IN","type":"{}"}}],"answers":[{}],"authorities":[],"additionals":[]}}]}}"#,
        domain, records[0].0, answers_str
    )
}

fn format_all_json(records: &[(String, Vec<DnsRecord>)], domain: &str, _record_types: &[String]) -> String {
    format_json(records, domain, _record_types)
}
